package com.runloyal.booking.domain; import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="staff_services") @IdClass(StaffService.Key.class) public class StaffService { @Id @Column(name="tenant_id") public UUID tenantId; @Id @Column(name="staff_id") public UUID staffId; @Id @Column(name="service_id") public UUID serviceId; public static class Key implements java.io.Serializable { public UUID tenantId,staffId,serviceId; public boolean equals(Object o){return o instanceof Key k&&Objects.equals(tenantId,k.tenantId)&&Objects.equals(staffId,k.staffId)&&Objects.equals(serviceId,k.serviceId);} public int hashCode(){return Objects.hash(tenantId,staffId,serviceId);} } }
